(()=>{const out={};for(const aa of [false,true]){const c=new OffscreenCanvas(8,8),g=c.getContext('webgl',{antialias:aa,preserveDrawingBuffer:true});const shader=(type,code)=>{const s=g.createShader(type);g.shaderSource(s,code);g.compileShader(s);return s},p=g.createProgram();g.attachShader(p,shader(g.VERTEX_SHADER,'attribute vec2 p;void main(){gl_Position=vec4(p,0.0,1.0);}'));g.attachShader(p,shader(g.FRAGMENT_SHADER,'precision highp float;uniform vec4 color;void main(){gl_FragColor=color;}'));g.linkProgram(p);g.useProgram(p);const b=g.createBuffer();g.bindBuffer(g.ARRAY_BUFFER,b);g.bufferData(g.ARRAY_BUFFER,new Float32Array([-.75,-.5,.75,-.5,0,.75]),g.STATIC_DRAW);const a=g.getAttribLocation(p,'p');g.vertexAttribPointer(a,2,g.FLOAT,false,0,0);g.enableVertexAttribArray(a);const color=g.getUniformLocation(p,'color'),read=()=>{const bytes=new Uint8Array(256);g.readPixels(0,0,8,8,g.RGBA,g.UNSIGNED_BYTE,bytes);return Array.from(bytes)};g.clearColor(0,0,0,1);g.clear(g.COLOR_BUFFER_BIT);g.uniform4f(color,1,0,0,1);g.drawArrays(g.TRIANGLES,0,3);const v=out[aa]={first:read(),again:read(),attributes:g.getContextAttributes()};g.enable(g.SCISSOR_TEST);g.scissor(0,0,4,8);g.uniform4f(color,0,1,0,1);g.drawArrays(g.TRIANGLES,0,3);v.overlap=read();g.clearColor(0,0,1,1);g.scissor(2,2,2,2);g.clear(g.COLOR_BUFFER_BIT);v.clear=read();c.width=9;c.width=8;v.reset=read()}return out})()